// The split-flap board's tiles: each character on its own tile with a seam
// across its middle, in a monospace face, on the desktop; a run of text on
// its ground in a terminal; bracketed in plain. Pixel geometry lives here,
// outside views/, which the gate keeps free of it.

import type { RenderChildren } from 'claude-code'
import type { Kit } from './kit'
import { boardCells } from './layout'
import { BOARD_RULE_ALT } from './words'

type Run = readonly [text: string, ink: string]
const TILE_PX = 10
const TILE_GAP = 1
const FLAP_PX = 20
const escape = (s: string): string => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
/** The runs as tiles: each run's characters, a blank tile between runs. */
const tilesOf = (runs: readonly Run[]): Array<readonly [string, string]> =>
  runs.flatMap(([text, ink], i) => [...(i === 0 ? [] : [[' ', ink] as const]), ...[...text].map(ch => [ch, ink] as const)])

/** The px the runs' tiles take: a flaps Svg's width. */
export const flapsWidth = (runs: readonly Run[]): number => tilesOf(runs).length * (TILE_PX + TILE_GAP) - TILE_GAP

/** `packed`: plain brackets the runs once, `[CACHE ! 30S]`, where it would
 *  bracket each, `[CACHE][! 30S]`: a row's last step, as filled drops its
 *  padding. Filled draws the same either way. */
export const flaps = (kit: Kit, o: Readonly<{ key: string; alt: string; runs: readonly Run[]; bg: string; seam: string; packed?: boolean }>): RenderChildren => {
  const { Svg, Text, Box, palette } = kit
  const { key, alt, runs, bg, seam } = o
  if (!Svg) {
    const packed = o.packed === true && !palette.filled
    // On the desktop, in plain, text set in a proportional face: its
    // capitals are measured as they draw, so the row is fitted to them.
    const said = packed ? [`[${runs.map(([text]) => text).join(' ')}]`] : runs.map(([text]) => (palette.filled ? text : `[${text}]`))
    const width = kit.measure.text < 1 ? Math.ceil(said.reduce((n, t) => n + boardCells(t, kit.measure), 0) + said.length - 1) : undefined
    return (
      <Box key={key} flexDirection="row" columnGap={1} {...(width === undefined ? {} : { width })}>
        {packed
          ? <Text key="0" color={palette.value}>{said[0]}</Text>
          : runs.map(([text, ink], i) =>
              palette.filled
                ? <Text key={String(i)} color={ink} backgroundColor={bg}>{text}</Text>
                : <Text key={String(i)} color={palette.value}>{`[${text}]`}</Text>)}
      </Box>
    )
  }
  const marks = tilesOf(runs).map(([ch, ink], i) => tileAt(i * (TILE_PX + TILE_GAP), ch, ink, bg, seam))
  return kit.svg({ key, alt, width: flapsWidth(runs), height: FLAP_PX }, marks.join(''))
}

/** A tile at `x`, as `flaps` draws one: its face, its character in `ink`,
 *  the seam across it. */
const tileAt = (x: number, ch: string, ink: string, bg: string, seam: string): string => {
  const glyph = `<text x="${x + TILE_PX / 2}" y="14.5" text-anchor="middle" xml:space="preserve" font-family="ui-monospace, monospace" font-size="12" font-weight="600" fill="${ink}">${escape(ch)}</text>`
  return `<rect class="tile" x="${x}" y="0" width="${TILE_PX}" height="${FLAP_PX}" rx="1.5" fill="${bg}"/>${glyph}<rect class="seam" x="${x}" y="9.5" width="${TILE_PX}" height="1" fill="${seam}"/>`
}
/** A blank at `x`: its glyph alone, no tile. */
const blankAt = (x: number): string => `<text x="${x + TILE_PX / 2}" y="14.5" xml:space="preserve"> </text>`

// ---- the open board's columns ------------------------------------------------

/** A column of the open board's flaps: its text, in its ink, in a column
 *  `cells` wide, the air after it included. */
export type FlapColumn = Readonly<{ text: string; ink: string; cells: number }>

/** A row of text on the desktop, and a rule's px. */
const ROW_PX = 24
const RULE_PX = 1

/** The columns a run of flaps spelling `text` takes: on the desktop at a
 *  tile's pitch; in plain, bracketed and measured as it draws; in a terminal
 *  a cell a character. */
export const flapCells = (kit: Kit, text: string): number => {
  if (text === '') return 0
  if (kit.Svg) return Math.ceil(([...text].length * (TILE_PX + TILE_GAP) - TILE_GAP) / kit.measure.pxPerCell)
  return Math.ceil(boardCells(kit.palette.filled ? text : `[${text}]`, kit.measure))
}

/** A line's flaps in fixed columns, so the board's lines align: tiles only
 *  where there are characters, never a blank one, the rest of each column
 *  the board's own ground. One Svg a line on the desktop, its alt the
 *  line's in words; a run of text in each column elsewhere, bracketed in
 *  plain. */
export const flapColumns = (kit: Kit, o: Readonly<{ key: string; alt: string; columns: readonly FlapColumn[]; bg: string; seam: string }>): RenderChildren => {
  const { Svg, Text, Box, palette, measure } = kit
  const { key, alt, columns, bg, seam } = o
  if (!Svg)
    return (
      <Box key={key} flexDirection="row" flexShrink={0}>
        {columns.map((c, i) => (
          <Box key={String(i)} width={c.cells} flexShrink={0}>
            {c.text === '' ? null
            : palette.filled ? <Text color={c.ink} backgroundColor={bg}>{c.text}</Text>
            : <Text color={palette.value}>{`[${c.text}]`}</Text>}
          </Box>
        ))}
      </Box>
    )
  const marks: string[] = []
  let at = 0
  for (const c of columns) {
    // A blank, the space in a word or the air after the column, keeps its
    // glyph, so the line still reads in words, and has no tile.
    ;[...(c.text === '' ? '' : `${c.text} `)].forEach((ch, i) => {
      const x = at + i * (TILE_PX + TILE_GAP)
      marks.push(ch === ' ' ? blankAt(x) : tileAt(x, ch, c.ink, bg, seam))
    })
    at += c.cells * measure.pxPerCell
  }
  return kit.svg({ key, alt, width: at, height: FLAP_PX }, marks.join(''))
}

/** A thin rule across the board, on the desktop alone: a terminal's would
 *  take a row. Like a stretched meter it has no width of its own: drawn
 *  twice as wide as the board's estimate, `cells`, and capped by its slot,
 *  it spans the board's inner width to the header's right edge, however
 *  wide the desktop draws a column. */
export const boardRule = (kit: Kit, key: string, cells: number, color: string): RenderChildren => {
  const width = 2 * Math.max(1, cells) * kit.measure.pxPerCell
  return kit.svg({ key, alt: BOARD_RULE_ALT, width, height: RULE_PX, stretch: true }, `<rect class="rule" x="0" y="0" width="${width}" height="${RULE_PX}" fill="${color}"/>`)
}

/** A board line's height, in the units the board is fitted in: on the
 *  desktop px, a row of text's 24, flaps alone their 20, and its rule's 1
 *  under it; elsewhere a row a line. */
export const boardLineHeight = (kit: Kit, o: Readonly<{ text: boolean; rule: boolean }>): number =>
  kit.Svg ? (o.text ? ROW_PX : FLAP_PX) + (o.rule ? RULE_PX : 0) : 1

/** What `rows` rows hold, in those units. */
export const boardBudget = (kit: Kit, rows: number): number => (kit.Svg ? rows * ROW_PX : rows)

files.hooks/views/departures-board.tsx:
// Departures open: one board on its dark ground under the collapsed row. Its
// header says DEPARTURES and the time now; quiet column headings follow, then
// a line per reading in the one order, the other limits after 7D (spec §5.3).
// ITEM, STATUS and TIME are flaps, tiles only where there are characters,
// each in a column of its own width so the lines align; REMARKS are plain
// dim text. The footer is the one every layout draws: the workspace strip,
// then Collapse and Hide band. Short of rows, the remarks give way first,
// then the lines in the spec's order; an amber line never does.

import type { RenderElement } from 'claude-code'
import { boardBudget, boardLineHeight, boardRule, flapCells, flapColumns, type FlapColumn } from '../flaps'
import type { Kit } from '../kit'
import { ROW_SLACK, boardCells } from '../layout'
import type { Readings } from '../reading'
import type { BandActions } from '../snapshot'
import type { Palette } from '../palette'
import { drawStrip } from '../strip'
import { BOARD_HEADINGS, BOARD_NOW, BOARD_NO_TIME, BOARD_TITLE, type BoardKey, type BoardRow } from '../words'
import { bodyRowsFor, footer, footerRoom } from './frame'

/** REMARKS cut to `tiles` characters, `…` last where cut. */
export const remarksFit = (remarks: string, tiles: number): string =>
  remarks.length <= tiles ? remarks : tiles <= 1 ? '' : `${remarks.slice(0, tiles - 1)}…`

/** Each reading's ITEM ink: its own, as an airline's code has its colour. */
export const ITEM_INK: Readonly<Record<BoardKey, Exclude<keyof Palette, 'filled'>>> = {
  cache: 'flapItemCache', spend: 'flapItemSpend', context: 'flapItemContext', '5h': 'flapItem5h', '7d': 'flapItem7d', other: 'flapText',
}

/** What gives way as rows run out, first to last (spec §5.3), CACHE and 7D
 *  together as the body's last step, after the remarks where leaving them
 *  out saves height. Calm lines alone give way (spec §2.1): an amber
 *  reading's line stays, as chips' cards leave their alert. */
const GIVE_WAY: ReadonlyArray<readonly string[]> = [['other'], ['headings'], ['spend'], ['context'], ['header'], ['5h'], ['cache', '7d']]

/** The columns of air after ITEM, STATUS and TIME. */
const COLUMN_GAP = 2
/** REMARKS narrower than this, and the lines leave them out. */
const REMARKS_LEAST = 8
/** The columns the board's paddingX takes, both sides. */
const BOARD_PAD = 2

type Line = Readonly<{ name: string; key: string; row?: BoardRow }>
/** The lines a board keeps, and whether they keep their remarks. */
type Plan = Readonly<{ lines: readonly Line[]; remarks: boolean }>
/** The board's columns: ITEM, STATUS and TIME as wide as their widest,
 *  air included; REMARKS what is left, none under REMARKS_LEAST; and the
 *  characters each flap column keeps. */
type Columns = Readonly<{ item: number; status: number; time: number; remarks: number; keep: Readonly<{ item: number; status: number; time: number }> }>
type FlapKey = 'item' | 'status' | 'time'
const FLAP_KEYS: readonly FlapKey[] = ['item', 'status', 'time']

/** The lines the board would draw with every row: each named by what gives
 *  way with it. */
const linesOf = (read: Readings): readonly Line[] => {
  const { rows } = read.board()
  const named = (key: BoardKey) => rows.filter(r => r.key === key).map(row => ({ name: key, row, key: `row:${key}` }))
  return [
    { name: 'header', key: 'row:header' },
    { name: 'headings', key: 'row:headings' },
    ...named('cache'), ...named('spend'), ...named('context'), ...named('5h'), ...named('7d'),
    ...rows.filter(r => r.key === 'other').map((row, i) => ({ name: 'other', row, key: `row:other:${i}` })),
  ]
}

/** A flap column's text as the columns keep it: whole, or cut with `…`
 *  where the room can't hold the widest. */
const kept = (cols: Pick<Columns, 'keep'>, key: FlapKey, text: string): string => remarksFit(text, cols.keep[key])

/** The columns for `rows` in `room`: each flap column as wide as its widest
 *  text and its heading, then the air. Where the three outgrow the room the
 *  widest is cut a character at a time; REMARKS take what is left. */
const columnsOf = (kit: Kit, rows: readonly BoardRow[], room: number): Columns => {
  const texts: Readonly<Record<FlapKey, readonly string[]>> = {
    item: rows.map(r => r.item), status: rows.map(r => r.status), time: rows.flatMap(r => r.time ?? []),
  }
  const keep = { item: 0, status: 0, time: 0 }
  for (const k of FLAP_KEYS) keep[k] = Math.max(0, ...texts[k].map(t => [...t].length))
  const widthOf = (k: FlapKey): number =>
    Math.max(Math.ceil(boardCells(BOARD_HEADINGS[k], kit.measure)), ...texts[k].map(t => flapCells(kit, remarksFit(t, keep[k])))) + COLUMN_GAP
  const total = () => FLAP_KEYS.reduce((n, k) => n + widthOf(k), 0)
  while (total() > room) {
    const widest = FLAP_KEYS.reduce((a, b) => (keep[b] > keep[a] ? b : a))
    if (keep[widest] <= 1) break
    keep[widest]--
  }
  const [item, status, time] = FLAP_KEYS.map(widthOf) as [number, number, number]
  const left = room - item - status - time
  return { item, status, time, remarks: left >= REMARKS_LEAST ? left : 0, keep }
}

/** A line's remark as drawn: cut to its column, none where it has none or
 *  the plan leaves them out. A column holds a capital a cell. */
const remarkOf = (row: BoardRow, cols: Columns, plan: Plan): string =>
  !plan.remarks || cols.remarks === 0 ? '' : remarksFit(row.remarks, cols.remarks)

/** The plan's height in the board's units, a rule under each line but the
 *  last on the desktop. */
const heightOf = (kit: Kit, plan: Plan, cols: Columns): number =>
  plan.lines.reduce((sum, l, i) => {
    const rule = i < plan.lines.length - 1 && l.name !== 'headings'
    const text = l.row === undefined || l.row.time === undefined || remarkOf(l.row, cols, plan) !== ''
    return sum + boardLineHeight(kit, { text, rule })
  }, 0)

/** The plan that fits `budget`: every line with its remarks; then, where
 *  that saves height, without them; then calm lines go in GIVE_WAY's order.
 *  Past the last step only amber lines are left, as many as fit. */
const fitPlan = (kit: Kit, lines: readonly Line[], cols: Columns, budget: number): Plan => {
  // A line of flaps alone is shorter than one with text on the desktop alone.
  const saves = kit.Svg !== undefined
  const plans: Plan[] = [{ lines, remarks: true }, ...(saves ? [{ lines, remarks: false }] : [])]
  let left = lines
  for (const names of GIVE_WAY) {
    left = left.filter(l => !names.includes(l.name) || l.row?.tone === 'amber')
    plans.push({ lines: left, remarks: !saves })
  }
  const fits = plans.find(p => heightOf(kit, p, cols) <= budget)
  if (fits !== undefined) return fits
  let last: Plan = { lines: left, remarks: !saves }
  while (last.lines.length > 0 && heightOf(kit, last, cols) > budget) last = { ...last, lines: last.lines.slice(0, -1) }
  return last
}

/** The header: DEPARTURES, and the time now at the other end where the
 *  zone is known; a rule under it on the desktop. */
const headerLine = (kit: Kit, read: Readings, inner: number, rule: boolean): RenderElement => {
  const { Box, Text, palette } = kit
  const now = read.board().now
  return (
    <Box key="row:header" flexDirection="column" flexShrink={0}>
      <Box key="line" flexDirection="row" justifyContent="space-between" columnGap={1}>
        <Text color={palette.flapDim}>{BOARD_TITLE}</Text>
        {now === undefined ? null : (
          <Box key="now" flexDirection="row" columnGap={1} flexShrink={0}>
            <Text color={palette.flapDim}>{BOARD_NOW}</Text>
            <Text color={palette.flapText} bold>{now}</Text>
          </Box>
        )}
      </Box>
      {rule ? boardRule(kit, 'rule', inner, palette.flapBg) : null}
    </Box>
  )
}

/** The column headings, quiet plain text over their columns. */
const headingsLine = (kit: Kit, cols: Columns, remarks: boolean): RenderElement => {
  const { Box, Text, palette } = kit
  return (
    <Box key="row:headings" flexDirection="row" flexShrink={0}>
      {FLAP_KEYS.map(k => (
        <Box key={k} width={cols[k]} flexShrink={0}>
          <Text color={palette.flapDim}>{BOARD_HEADINGS[k]}</Text>
        </Box>
      ))}
      {remarks ? <Text key="remarks" color={palette.flapDim}>{BOARD_HEADINGS.remarks}</Text> : null}
    </Box>
  )
}

/** A reading's line: ITEM in its own ink, STATUS amber where the reading
 *  is, TIME, each flaps in its column, or a dim dash for no TIME; then its
 *  remark in plain dim text; a rule under it on the desktop. */
const readingLine = (kit: Kit, l: Line, row: BoardRow, cols: Columns, remark: string, inner: number, rule: boolean): RenderElement => {
  const { Box, Text, palette, oneLine } = kit
  const time = row.time
  const flapsOf: FlapColumn[] = [
    { text: kept(cols, 'item', row.item), ink: palette[ITEM_INK[row.key]], cells: cols.item },
    { text: kept(cols, 'status', row.status), ink: row.tone === 'amber' ? palette.flapAmber : palette.flapText, cells: cols.status },
    ...(time === undefined ? [] : [{ text: kept(cols, 'time', time), ink: palette.flapText, cells: cols.time }]),
  ]
  return (
    <Box key={l.key} flexDirection="column" flexShrink={0}>
      <Box key="line" flexDirection="row">
        {flapColumns(kit, { key: 'flaps', alt: row.alt, columns: flapsOf, bg: palette.flapBg, seam: palette.flapSeam })}
        {time !== undefined ? null : (
          <Box key="time" width={cols.time} flexShrink={0}>
            <Text color={palette.flapDim}>{BOARD_NO_TIME}</Text>
          </Box>
        )}
        {remark === '' ? null : oneLine({ key: 'remarks', color: palette.flapDim }, remark)}
      </Box>
      {rule ? boardRule(kit, 'rule', inner, palette.flapBg) : null}
    </Box>
  )
}

/** The board, its lines fitted to the body's rows, on its dark ground;
 *  nothing when no line fits. */
const board = (kit: Kit, read: Readings, collapsedRows: number): RenderElement | null => {
  const { Box, Svg, palette } = kit
  const inner = Math.max(0, kit.columns - ROW_SLACK - BOARD_PAD)
  const cols = columnsOf(kit, read.board().rows, inner)
  const plan = fitPlan(kit, linesOf(read), cols, boardBudget(kit, bodyRowsFor(read.frame.maxRows, collapsedRows, 0)))
  if (plan.lines.length === 0) return null
  const remarks = plan.remarks && cols.remarks > 0
  return (
    <Box
      key="board"
      flexDirection="column"
      marginTop={1}
      paddingX={1}
      backgroundColor={palette.filled ? palette.boardBg : undefined}
      {...(Svg ? { borderStyle: 'round', borderColor: palette.boardBg } : {})}
    >
      {plan.lines.map((l, i) => {
        const rule = i < plan.lines.length - 1
        return l.row !== undefined ? readingLine(kit, l, l.row, cols, remarkOf(l.row, cols, plan), inner, rule)
          : l.name === 'header' ? headerLine(kit, read, inner, rule)
          : headingsLine(kit, cols, remarks)
      })}
    </Box>
  )
}

/** Departures open: the board, then the footer every layout draws, the
 *  workspace strip in its row. */
export const openBoard = (kit: Kit, read: Readings, act: BandActions, collapsedRows: number): RenderElement[] => {
  const ws = read.workspace
  const strip = ws === undefined ? undefined : drawStrip(kit, ws, 'footer', 0, kit.columns - ROW_SLACK - footerRoom(kit))
  return [board(kit, read, collapsedRows), footer(kit, act, strip)].filter(e => e !== null)
}

